pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "", ""); }
    function testRegression_property() public {
        c.burn(100);
        uint256 bal = c.balanceOf(address(this));
        uint256 total = c.totalSupply();
        assertTrue(bal == total, "balanceOf(owner) should equal totalSupply after burn");
    }
}
